BG={"JPG":"JPEG was standardised in 1992 and remains the most widely used photo format. It splits the image into 8×8 blocks and discards fine detail the eye notices least, which is why heavy compression shows blocky artefacts around edges and text.",
"PNG":"PNG was created in the mid-1990s as a patent-free replacement for GIF. It compresses losslessly with the same algorithm as ZIP, so files are exact copies of the pixels – perfect for screenshots, diagrams and logos, but large for photographs.",
"WEBP":"WebP was released by Google in 2010, based on the VP8 video codec. One format covers lossy photos, lossless graphics, transparency and animation. Google reports lossy WebP files 25–34% smaller than comparable JPEGs.",
"AVIF":"AVIF is based on the royalty-free AV1 video codec from the Alliance for Open Media. It supports HDR, wide colour, transparency and animation, and usually beats both JPG and WebP on size – at the cost of slower encoding.",
"TIFF":"TIFF dates from 1986 and is a flexible container used by scanners, publishers and archives. It can hold several pages, high bit depths and CMYK colour, and is often stored uncompressed or with lossless LZW compression.",
"BMP":"BMP is the native bitmap format of Windows, used since the early days of Windows Paint. It normally stores raw, uncompressed pixels, so files are big and rarely used on the web today.",
"GIF":"GIF was introduced by CompuServe in 1987. It is limited to 256 colours per frame but supports simple animation and on/off transparency, which is why it remains popular for short loops and reactions.",
"ICO":"ICO is the Windows icon container. One .ico file can hold several sizes (such as 16, 32 and 48 px) so Windows and browsers can pick the sharpest version; it is the classic format for favicon.ico.",
"SVG":"SVG is an open W3C standard that describes images as shapes, paths and text in XML. Because it is vector-based, an SVG stays perfectly sharp at any size, from a favicon to a billboard, and can be edited in code or in design apps."}
F={
"JPG":dict(full="JPEG (Joint Photographic Experts Group)",comp="Lossy",alpha="No",anim="No",col="16.7 million (8-bit per channel)",sup="Everywhere – every browser, phone, OS and app",best="Photos, e-mail, uploads to any site",size="Small for photos",year="1992"),
"PNG":dict(full="PNG (Portable Network Graphics)",comp="Lossless",alpha="Yes, full alpha",anim="APNG only (limited)",col="Up to 16.7 million + alpha",sup="Everywhere",best="Screenshots, logos, graphics with text, transparency",size="Large for photos, small for flat graphics",year="1996"),
"WEBP":dict(full="WebP, developed by Google",comp="Lossy or lossless",alpha="Yes",anim="Yes",col="16.7 million + alpha",sup="All current major browsers (Safari since version 14); some older desktop apps cannot open it",best="Web pages – smaller than JPG and PNG",size="Usually smaller than JPG/PNG at similar quality",year="2010"),
"AVIF":dict(full="AVIF (AV1 Image File Format)",comp="Lossy or lossless",alpha="Yes",anim="Yes",col="8, 10 or 12-bit, HDR capable",sup="Chrome, Edge, Firefox and Safari 16+; many editors and older apps cannot open it",best="Modern websites wanting the smallest files",size="Often the smallest at similar quality",year="2019"),
"TIFF":dict(full="TIFF (Tagged Image File Format)",comp="Uncompressed or lossless (LZW/ZIP); JPEG inside TIFF possible",alpha="Yes",anim="No (but multi-page)",col="8/16-bit per channel, CMYK possible",sup="Image editors, print and scanning software; most browsers except Safari do not display it",best="Print, scanning, archiving, professional editing",size="Very large",year="1986"),
"BMP":dict(full="BMP (Windows Bitmap)",comp="Usually uncompressed",alpha="Rarely supported",anim="No",col="Up to 16.7 million",sup="Windows and most editors; not ideal for the web",best="Legacy Windows software",size="Very large",year="1990s"),
"GIF":dict(full="GIF (Graphics Interchange Format)",comp="Lossless, but limited to 256 colours",alpha="1-bit (on/off) only",anim="Yes",col="256 per frame",sup="Everywhere",best="Simple animations, tiny graphics",size="Small for flat graphics, large for photos",year="1987"),
"ICO":dict(full="ICO (Windows icon)",comp="PNG or BMP images inside",alpha="Yes",anim="No",col="Up to 32-bit",sup="Windows, browsers (favicons)",best="Favicons and Windows icons",size="Tiny",year="1985"),
"SVG":dict(full="SVG (Scalable Vector Graphics)",comp="Vector (XML text), not pixels",alpha="Yes",anim="Yes (CSS/SMIL)",col="Unlimited",sup="All browsers, design apps, cutting machines (Cricut, Silhouette)",best="Logos, icons, illustrations that must scale",size="Tiny for simple shapes, large for photo-like traces",year="2001"),
}
R={ # pair: (reasons, notes)
("webp2png"):("WEBP","PNG",["Open images saved from websites in apps that do not accept WebP, such as older versions of Photoshop, Word or Windows Photo Viewer.","Keep transparency – PNG supports full alpha, just like WebP.","Edit without further quality loss: PNG is lossless, so repeated saves do not add artefacts.","Upload to forms and print services that only accept PNG or JPG."],"Converting a lossy WebP to PNG cannot restore detail that WebP compression already removed, but it stops any further loss. Expect the PNG to be larger – often 2–5× for photos – because PNG stores every pixel exactly."),
("jpg2webp"):("JPG","WEBP",["Speed up websites: WebP photos are typically noticeably smaller than equivalent JPGs, which improves Core Web Vitals such as Largest Contentful Paint.","Save storage and bandwidth for galleries, shops and blogs.","Follow PageSpeed Insights' advice to “serve images in modern formats”.","Convert whole folders at once for a WordPress or Shopify upload."],"Quality 75–85 is the sweet spot for photos: visually almost identical to the JPG at a clearly smaller size. Converting from JPG re-compresses an already lossy image, so do not go very low."),
("png2webp"):("PNG","WEBP",["Shrink screenshots, graphics and transparent images for the web while keeping the alpha channel.","Improve page speed scores by serving a modern format.","Reduce the size of image-heavy documentation and landing pages.","Replace large PNG hero images that slow down mobile pages."],"For graphics with text and sharp edges, use quality 90–100 to avoid blur around letters; for photos saved as PNG, 75–85 gives big savings."),
("avif2jpg"):("AVIF","JPG",["Open AVIF images downloaded from websites in apps that do not support AVIF yet, such as older Windows Photos, Office or many editors.","Share images by e-mail or messaging with people on older devices.","Upload to sites and forms that only accept JPG.","Print at shops whose software expects JPG."],"JPG has no transparency, so transparent areas of an AVIF are filled with the background colour you choose (white by default). Use quality 90+ for prints and 80–85 for sharing."),
("jpg2avif"):("JPG","AVIF",["Get the smallest possible image files for a fast website.","Serve modern formats to supporting browsers, with JPG as a fallback.","Save storage for large photo libraries on the web.","Experiment with next-generation compression without installing tools."],"AVIF encoding is heavier than JPG, so large batches take longer on older phones. Check that your website or CMS accepts AVIF uploads before converting everything."),
("tiff2jpg"):("TIFF","JPG",["Make huge scanner or camera TIFFs small enough to e-mail or upload.","View images in browsers and phones that cannot display TIFF.","Share scans of documents and photos quickly.","Post print-quality images online."],"Multi-page TIFF files (for example scanned documents and faxes) are common; this converter turns the first page into a JPG. To keep all pages, convert the TIFF to PDF with [Image to PDF](/image-to-pdf/)."),
("jpg2tiff"):("JPG","TIFF",["Supply images to printers, publishers or archives that require TIFF.","Use in desktop publishing and scanning workflows.","Store a lossless working copy for further editing so no more JPG loss is added.","Meet document management or legal submission requirements."],"A TIFF made from a JPG is lossless from that point on but cannot recover detail lost in the original JPG compression. Files will be much larger."),
("bmp2jpg"):("BMP","JPG",["Shrink uncompressed BMP files – often 10× or more – for e-mail and the web.","Open old Windows Paint images on phones and Macs easily.","Upload to websites that do not accept BMP.","Free up disk space from legacy image archives."],"BMP stores every pixel uncompressed, so JPG at quality 90 usually looks the same with a fraction of the size."),
("png2ico"):("PNG","ICO",["Create a favicon.ico for your website.","Make icons for Windows shortcuts, folders and apps.","Keep transparency in the icon.","Turn a logo into an icon in seconds."],"Start from a square PNG of at least 256×256 pixels; non-square images are fitted into a square. For a complete favicon set with apple-touch-icon and manifest sizes, use the [Favicon generator](/favicon-generator/)."),
("svg2png"):("SVG","PNG",["Use vector logos and icons in apps that only accept pixel images, such as Word, PowerPoint, social media and e-mail signatures.","Render an SVG at a precise width for a website or print.","Share graphics with people who cannot open SVG files.","Create PNG previews of icon sets."],"SVG has no fixed pixel size; set *Max width* to control the output size – for example 2000 px for print or 512 px for an app icon. Transparent areas stay transparent in PNG."),
("png2svg"):("PNG","SVG",["Turn a logo or icon into a scalable vector for print, signage or a website.","Prepare cut files for Cricut, Silhouette and laser cutters.","Make simple artwork resizable without pixelation.","Reduce file size for flat graphics with few colours."],"This is *tracing*: the image is analysed and redrawn as coloured vector shapes. It works best for logos, icons, silhouettes and drawings with clear edges and few colours. Photos produce very large SVGs that still look like posterised art. For Cricut, choose 2 colours (black & white) and a high-contrast image."),
("gif2png"):("GIF","PNG",["Get a still image from an animated GIF (the first frame).","Edit a GIF graphic without the 256-colour limit.","Use the image in apps that handle PNG better.","Keep transparency for logos and icons."],"PNG keeps the GIF's colours exactly. Animated GIFs become a single still image of the first frame; to keep animation, convert to MP4 or WebP instead."),
}
SLUG={"webp2png":"webp-to-png","jpg2webp":"jpg-to-webp","png2webp":"png-to-webp","avif2jpg":"avif-to-jpg","jpg2avif":"jpg-to-avif","tiff2jpg":"tiff-to-jpg","jpg2tiff":"jpg-to-tiff","bmp2jpg":"bmp-to-jpg","png2ico":"png-to-ico","svg2png":"svg-to-png","png2svg":"png-to-svg","gif2png":"gif-to-png"}
IMGPRIV="Images are decoded and converted inside your browser using the built-in image engine (and WebAssembly encoders for AVIF and tracing for SVG). Nothing is uploaded or stored on a server, there is no account, and the page keeps working offline once loaded – handy for personal photos, ID scans and client artwork."
def gen(k):
    A,B,reasons,note=R[k];a,b=F[A],F[B];s=SLUG[k];kw=KW.get(s,{});al=A.lower();bl=B.lower()
    lossy=B in("JPG","WEBP","AVIF");sec=[]
    sec.append([f"Convert {A} to {B} online, free",f"This free {A} to {B} converter turns {a['full']} images into {b['full']} files directly in your browser. Drop one image or a whole folder, choose quality and size, and download a single {B} or a ZIP – no upload, no sign-up and no watermark. It works on Windows, Mac, Linux, iPhone and Android in any modern browser."])
    sec.append([f"How to convert {A} to {B}",{"steps":[f"Drop your {A} files on the page (or tap to choose).",f"Check that the output format is {B}; adjust quality, background or max width if needed.","Press Convert.",f"Download the {B} – or a ZIP when you converted several files."]}])
    sec.append([f"{A} vs {B}: what is the difference?",{"table":[["",A,B],["Compression",a['comp'],b['comp']],["Transparency",a['alpha'],b['alpha']],["Animation",a['anim'],b['anim']],["Colours",a['col'],b['col']],["Support",a['sup'],b['sup']],["Best for",a['best'],b['best']],["File size",a['size'],b['size']],["Introduced",a['year'],b['year']]]}])
    sec.append([f"Why convert {A} to {B}?",{"list":reasons},note])
    opts=[f"**Quality** – {'lower values give smaller files; 80–90 is a good default' if lossy else 'only affects lossy formats; '+B+' output is lossless'}.",
          "**Background colour** – used when the output is JPG, to fill transparent areas (white by default).",
          "**Max width** – scales larger images down proportionally; leave empty to keep the original size.",
          "**Make white background transparent** – for PNG, WebP, AVIF, GIF and ICO output, turns near-white pixels transparent, useful for logos on white."]
    if B=="SVG":opts+=["**SVG trace colours** – 2 for black-and-white cut files, 16 for typical logos, up to 64 for more detail.","**SVG detail** – *High* keeps small shapes (bigger file), *Smooth* drops specks for cleaner, smaller files."]
    sec.append(["Options explained",{"list":opts}])
    if lossy: sec.append([f"How to convert {A} to {B} without losing quality",f"{B} is a lossy format, so some information is always discarded – the goal is to make the loss invisible. Use quality 90 or higher for images you will print or edit again, 80–85 for websites and sharing, and avoid converting the same image repeatedly. Do not upscale: keep *Max width* empty unless you want a smaller image. The result message shows the size before and after, so you can find the best balance."])
    else: sec.append([f"Is {A} to {B} conversion lossless?",f"{B} {'stores pixels exactly' if B in('PNG','TIFF','BMP','GIF','ICO') else 'is vector'}, so the conversion adds no new compression artefacts{' – but GIF is limited to 256 colours, so photos lose colour detail' if B=='GIF' else ''}. Detail already lost in a lossy {A} cannot be brought back; the {B} will look exactly like the {A} you started with."])
    sec.append([f"About the {A} and {B} formats",BG[A],BG[B]])
    sec.append(["Convert many images at once",f"Select or drop as many {A} files as you like. They are converted one after another on your device and packed into a single ZIP for download. Because nothing is uploaded, batch speed depends only on your computer or phone – typically a fraction of a second per photo on a laptop."])
    sec.append([f"Convert {A} to {B} on Windows, Mac, iPhone and Android",f"There is nothing to install: open this page in Chrome, Edge, Firefox or Safari. On iPhone and iPad, choose images from Photos or Files and save the result to Files; on Android, results go to Downloads. On a PC or MacBook, you can drag files straight from a folder. Built-in apps can sometimes export {B} too, but a browser converter is the same on every device and handles batches."])
    sec.append(["Troubleshooting",{"table":[["Problem","Fix"],["Output is too large","Lower quality or set a max width"+("" if lossy else f"; {B} is lossless, consider WebP for the web")],["Transparent areas turned white","JPG has no transparency – choose PNG or WebP"],["File will not open in an old app","Convert to JPG or PNG, which are universally supported"],["Colours look slightly different","Some images use wide-gamut colour profiles; browsers convert to sRGB"],["Phone browser is slow on big batches","Convert in smaller groups or use a computer"]]}])
    sec.append(["Glossary",{"table":[["Term","Meaning"],["Lossy","Compression that discards detail to save space"],["Lossless","Compression that keeps every pixel exact"],["Alpha channel","Per-pixel transparency information"],["sRGB","The standard colour space for screens and the web"]]}])
    sec.append(["Privacy",IMGPRIV]);rel=[("Image converter","image-converter"),("Compress image","compress-image"),("Resize image","resize-image"),(f"{B} to {A}" if f"{bl}-to-{al}" in [v for v in SLUG.values()] else "Image to PDF",f"{bl}-to-{al}" if f"{bl}-to-{al}" in SLUG.values() else "image-to-pdf"),("Crop image","crop-image")]
    sec.append(["Related tools",["[%s](/%s/)"%(n,x) for n,x in rel]])
    faq=[Q(f"How do I convert {A} to {B}?",f"Drop the {A} files here, keep {B} as the output and press Convert."),
         Q(f"Is this {A} to {B} converter free?","Yes – free, unlimited, no sign-up and no watermark."),
         Q(f"Can I convert {A} to {B} without losing quality?",("Use quality 90+; "+B+" is lossy, but the loss is invisible at high settings.") if lossy else f"Yes, {B} adds no further loss."),
         Q(f"Does {B} support transparency?",("Yes." if b['alpha'].startswith("Yes") else "Only on/off transparency." if B=="GIF" else "No – transparent areas are filled with the background colour.")),
         Q("Can I convert several files at once?","Yes, select many files and download a ZIP."),
         Q("Are my images uploaded?","No. Conversion happens in your browser."),
         Q(f"Does it work on iPhone, Android and Mac?","Yes, in any modern browser, with nothing to install."),
         Q(f"Can I resize while converting?","Yes, set a max width in pixels.")]
    if B=="SVG":faq.append(Q("Can I use the SVG with Cricut?","Yes – choose 2 trace colours and a high-contrast image, then upload the SVG to Design Space."))
    if A=="WEBP":faq.append(Q("Why are images saved as WebP?","Websites use WebP because it is smaller than JPG and PNG, which makes pages load faster."))
    E(S,k,title=f"{A} to {B} Converter – Free, Batch, No Upload"[:60],desc=f"Convert {A} to {B} free in your browser: batch files, quality and size control{', SVG tracing' if B=='SVG' else ', transparency'}. No upload, no sign-up, no watermark."[:155],
      compareTitle="{tool}: {brand} vs CloudConvert, Convertio and FreeConvert",compareCols=CC,sections=sec,
      compare=CB([["Batch conversion with ZIP","Yes"],["Quality & max width","Yes"],["Works offline","Yes"]]),faq=faq,related=[x for _,x in rel])
for k in R:gen(k)
X=[["Raster vs vector: what tracing does","A PNG is a grid of pixels. An SVG describes shapes – paths with curves and fill colours. Converting PNG to SVG therefore means *tracing*: the converter reduces the image to a set number of colours, finds the outline of every area of each colour, and fits smooth curves and straight lines to those outlines. The result is a real vector file you can scale, recolour and edit node by node in Inkscape, Illustrator, Figma or Affinity Designer, not just a PNG wrapped inside an SVG file (which is what some converters produce)."],
 ["Choosing the number of colours",{"table":[["Colours","Best for","Result"],["2","Cricut/Silhouette cut files, stencils, line art, signatures","Clean black shapes, smallest file"],["4–8","Simple logos, icons, badges","Flat colour areas, crisp edges"],["16","Most logos and illustrations (default)","Good balance of fidelity and size"],["32–64","Detailed illustrations, gradients","Closer to the original, larger file"]]},"Start with the default and look at the preview in a browser. If colours are missing, increase the number; if you see blotches and noise, decrease it or choose *Smooth* detail."],
 ["How to prepare a PNG for a clean SVG",{"list":["Use the largest, sharpest version of the image you have – tracing a tiny or blurry image gives wobbly outlines.","Crop away unneeded background with [Crop image](/crop-image/).","Increase contrast and remove JPG-style noise before tracing.","Remove the background first with [Remove background](/remove-background/) if you only want the subject.","For line art, convert to black and white so the tracer sees two clear colours."]}],
 ["PNG to SVG for Cricut and cutting machines","Cutting machines follow vector paths, so they need SVG (or DXF) files rather than PNG. For a single-layer cut, choose **2 colours** so the design becomes solid black shapes on white, and *Smooth* detail to drop specks that would turn into tiny cuts. Upload the SVG in Cricut Design Space with *Upload → Upload image*, then check the cut preview: every closed shape becomes a cut line. Use *Weld* or *Attach* in Design Space to keep separate pieces together. For multi-colour layered vinyl, use 4–8 colours; each colour becomes a separate group you can assign to its own layer."],
 ["PNG to SVG in Inkscape or Illustrator vs online","Inkscape (*Path → Trace Bitmap*) and Illustrator (*Image Trace*) offer fine control over thresholds, corners and noise, and are the right choice for professional logo redraws. They take time to learn and install. This converter gives you a good first trace in seconds, on any device, without uploading client artwork. You can always open the SVG in Inkscape or Illustrator afterwards to refine nodes, merge shapes or change colours."],
 ["Limitations of automatic tracing",{"list":["Photos become poster-like art with thousands of paths and large files – keep photos as PNG, JPG or WebP.","Text in the image is traced as shapes, not editable text; retype it in a design app if needed.","Very thin lines may break up; trace at a larger size or choose High detail.","Gradients are approximated with bands of flat colour.","Huge images are scaled to about 1,000 px (1,600 px in High detail) for tracing, then output at the original dimensions.","Soft shadows and glows turn into stepped rings of colour; remove them from the artwork first if you can.","JPG-compressed sources add speckles around edges – start from the original PNG where possible."]}],
 ["Is PNG to SVG conversion free here?","Yes. There are no limits on the number of images, no daily quota, no watermark and no account. Tracing runs on your own device with the open-source ImageTracer library, so there is no server cost and no reason to restrict you – the only limit is your device's memory for extremely large images. Batch tracing also works: drop several PNGs and download all the SVGs together as one ZIP, each traced with the same colour and detail settings, which is ideal for converting a whole icon set in a single pass."],
 ["Checking and using your SVG",'Open the downloaded SVG in your browser to see it at any zoom level. In a website, use it in an <img> tag or inline it to style colours with CSS. In Word and PowerPoint (Microsoft 365), insert it as a picture – it stays sharp when resized. For print, most print shops accept SVG or will ask for PDF; convert with a design app or use [Image to PDF](/image-to-pdf/) for a pixel version.'],
 ["Worked example: a café logo for signage","A café owner has only a 600 × 600 px PNG of the logo, but the sign maker needs a vector file for a 2-metre sign. Drop the PNG, choose 8 colours (the logo has a dark brown, a cream and an orange accent plus their anti-aliased edges), tick *Make white background transparent* and keep *Normal* detail. Convert, then open the SVG in the browser and zoom to 800%: the edges stay smooth instead of turning into blocks. The sign maker can import the SVG straight into their software, or open it in Inkscape to clean a couple of small nodes. Total time: under a minute, with the artwork never leaving the computer."],
 ["SVG vs EPS, PDF and DXF",{"table":[["Format","Typical use","Notes"],["SVG","Web, apps, Cricut/Silhouette, modern design tools","Open standard, text-based, easy to edit"],["EPS","Older print workflows","Being replaced by PDF; many apps import it"],["PDF (vector)","Print shops, sharing","Can contain vectors; good for final artwork"],["DXF","CAD, laser and CNC cutters","Lines only, no fills"]]},"SVG is usually the most convenient starting point: most design and CAD tools import it and can export the other formats if a supplier insists on one."],
 ["Keeping SVG file size small","A trace with many colours and small details can contain thousands of paths. To keep files light for websites: reduce the number of colours, choose *Smooth* detail to drop tiny specks, crop the image tightly before tracing, and avoid tracing photos. For web use you can also run the result through an SVG optimiser such as SVGO, which removes redundant data without changing the look."],
 ["Who uses PNG to SVG conversion",{"list":["**Small businesses** turning a logo into a vector for signs, vehicle wraps and embroidery.","**Crafters** making Cricut and Silhouette cut files for vinyl, iron-on and paper.","**Web developers** replacing blurry PNG icons with crisp, scalable SVGs.","**Laser-engraving and CNC hobbyists** creating paths from drawings.","**Teachers and students** vectorising diagrams for slides and posters."]}],
 ["Step-by-step: from PNG to a finished vector",{"steps":["Start with the biggest, cleanest PNG you have.","Crop and, if needed, remove the background.","Pick colours: 2 for cut files, 8–16 for logos.","Choose detail: Normal first; High for fine lines, Smooth for cleaner shapes.","Convert and open the SVG in your browser at high zoom.","If it looks noisy, lower colours or pick Smooth and run again.","Optionally refine nodes or recolour in Inkscape, Illustrator or Figma."]},"Because the original PNG is never changed and every run takes seconds, it is quick to try two or three settings and keep the best one."],
 ["Can I change PNG to SVG just by renaming?","No. Renaming *logo.png* to *logo.svg* does not change the content – apps will refuse to open it or show an error. Some online tools also just embed the PNG pixels inside an SVG wrapper, which still pixelates when enlarged. A real conversion must trace the pixels into vector paths, which is what this tool does; you can check by opening the SVG in a text editor and seeing *path* elements rather than a long base64 image."],
 ["Make the background transparent","Tick *Make white background transparent* before converting and white areas become empty rather than white shapes – essential for logos that will sit on coloured backgrounds, and for cut files where you do not want a big rectangle around the design."]]
sec=S["png2svg"]["sections"];i=[j for j,x in enumerate(sec) if x[0]=="Privacy"][0];S["png2svg"]["sections"]=sec[:i]+X+sec[i:]
dump(S,"9d")
